function makeLevel(){const biome=biomes[level%biomes.length];seed=(seed+0x9e3779b9+level*7919)>>>0;platforms=[];hazards=[];sights=[];particles=[];trees=[];trailSigns=[];levelSights=0;cameraX=0;let x=0,y=370;platforms.push({x,y,w:155,h:70,main:true});
  // A long, branching trail: the far end is deliberately beyond one screenful of travel.
  for(let i=1;i<=38;i++){x+=108+rng()*42;y=clamp(y+(rng()-.56)*105,185,432);let w=74+rng()*52;if(i===38)w=165;const p={x:Math.round(x),y:Math.round(y),w:Math.round(w),h:540-Math.round(y),main:true,index:i};platforms.push(p);if(i>1&&i<38&&rng()<.38){const type=rng()<.52?'thorn':'puddle';let hx=p.x+18+rng()*Math.max(8,p.w-48);hazards.push({x:hx,y:p.y-2,w:type==='thorn'?22:28,type,hit:false})}}
  worldEnd=platforms[platforms.length-1].x+platforms[platforms.length-1].w+100;goalX=platforms[platforms.length-1].x+platforms[platforms.length-1].w-28;
  // Side ledges and occasional lower stepping stones make optional routes and recoveries.
  for(let i=2;i<38;i++){const p=platforms[i];if(rng()<.57){const sw=48+Math.round(rng()*38),sx=p.x+Math.round((rng()-.5)*72),sy=clamp(p.y-48-Math.round(rng()*31),168,405);platforms.push({x:sx,y:sy,w:sw,h:540-sy,side:true})}if(i%6===0&&rng()<.72)platforms.push({x:p.x+32,y:Math.min(470,p.y+42),w:37,h:500,side:true,small:true})}
  const count=1+Math.floor(rng()*3),spots=[];while(spots.length<count){const idx=4+Math.floor(rng()*32);if(!spots.includes(idx))spots.push(idx)}spots.sort((a,b)=>a-b);spots.forEach((idx,n)=>{const base=platforms[idx],sw=62,sx=base.x+Math.round(base.w*.5)-sw/2,sy=clamp(base.y-68-(n%2)*10,145,385);platforms.push({x:sx,y:sy,w:sw,h:540-sy,side:true,sightPlatform:true});sights.push({x:sx+sw/2,y:sy-1,found:false,kind:level%4,name:biome.sight})});
  // A readable trail language: blazed trees at forks, wooden markers toward a sight or the summit.
  for(let i=1;i<38;i++){const p=platforms[i];if(i%3===0&&rng()<.8)trees.push({x:p.x+12+Math.round(rng()*Math.max(8,p.w-24)),y:p.y,size:.8+rng()*.55,marked:i%6===0,tone:Math.floor(rng()*3)});if(i%5===2){const target=sights.find(s=>!s.found&&s.x>p.x)||goalX;trailSigns.push({x:p.x+p.w-18,y:p.y,targetX:target,label:target===goalX?'TRAIL':'SIGHT'})}}
  player.x=28;player.y=platforms[0].y-player.h;player.vx=player.vy=0;player.onGround=false;player.coyote=0;player.buffer=0;player.facing=1;checkpoint={x:player.x,y:player.y};$('chapter').textContent=biome.name;$('progress').textContent=`LEVEL ${String(level+1).padStart(2,'0')} · 04`;updateHUD()}

